599	
600	        handler: Handler,
601	        parser: Parser,
602	        utf8decoder: UTF8Decoder,
603	        continuation: ?continuationpkg.Tracker,
604	
605	        pub const Options = struct {
606	            /// The handler initial value, must be set.
607	            handler: Handler,
608	
609	            /// Allocator to use. If this is not set then the stream
610	            /// will be fully allocation free. There are some operations
611	            /// that will be dropped in this case such as OSC 52 clipboard
612	            /// ops.
613	            allocator: ?Allocator = null,
614	
615	            /// Maximum size in bytes of the continuation suffix. If this is
616	            /// null or zero then continuation tracking is disabled. This is
617	            /// only applied when `allocator` is non-null; without an allocator
618	            /// continuation tracking is disabled. Feeding this continuation
619	            /// suffix into an equivalent stream at ground reconstructs the
620	            /// unfinished state without repeating committed terminal effects.
621	            /// Continuation tracking is only supported by TerminalStream.
622	            continuation_max_bytes: ?usize = null,
623	
624	            /// The most bytes to keep from each OSC sequence whose number
625	            /// the OSC parser does not implement. Zero, the default,
626	            /// discards these sequences. Any other value sends them to the
627	            /// handler as `osc_unknown` actions. See
628	            /// `osc.Parser.unknown_max_bytes` for how the limit behaves.
629	            ///
630	            /// This only affects OSC. Other kinds of unknown sequences,
